<script setup lang="ts">
import type { ApiEnvelope } from '~/types/api'
import type { Customer, Page, Plan, Subscription } from '~/types/billing'
import { money, billingDate } from '~/utils/billing'
const { can } = useAccess()
definePageMeta({ layout:'admin', middleware:'management' })
const { request } = useApi(), route = useRoute()
const { rows, pagination, pending, error, refresh, search, status, page, message, failure, saving, mutate } = await useManagement<Subscription>('subscriptions')
const { data:plans } = await useAsyncData('subscription-plans',()=>can('plans.view')?request<ApiEnvelope<Plan[]>>('management/plans'):Promise.resolve({data:[]} as ApiEnvelope<Plan[]>))
const editing = ref(false), cancelling = ref<Subscription | null>(null), customerSearch = ref(''), customers = ref<Customer[]>([]), finding = ref(false), searchInput = ref('')
const form = reactive({ user_id:0, plan_id:0, interval:'month', status:'active', amount:'', starts_at:new Date().toISOString().slice(0,10), ends_at:'', notes:'' })
async function findCustomers() { finding.value=true; try { customers.value=(await request<ApiEnvelope<Page<Customer>>>('management/customers',{query:{search:customerSearch.value,status:'active'}})).data.data.filter(c=>c.role==='user') } catch { failure.value='Could not load customers.' } finally {finding.value=false} }
function begin() { failure.value=''; editing.value=true; void findCustomers() }
async function assign() { if(await mutate('management/subscriptions',{...form,amount:Math.round(Number(form.amount)*100)})) editing.value=false }
watch(()=>[form.plan_id,form.interval],()=>{ const plan=plans.value?.data.find(p=>p.id===Number(form.plan_id)); const amount=form.interval==='month'?plan?.monthly_price:plan?.yearly_price; form.amount=amount==null?'':String(amount/100) })
onMounted(async()=>{ if(route.query.customer) { try {const result=await request<ApiEnvelope<{user:Customer}>>(`management/customers/${Number(route.query.customer)}`); search.value=result.data.user.email; customerSearch.value=result.data.user.email; form.user_id=result.data.user.id } catch { failure.value='Customer not found.' } } })
</script>
<template><div><div class="flex justify-between gap-4"><div><p class="eyebrow">Customer lifecycle</p><h1 class="page-title mt-2">Subscriptions</h1><p class="mt-2 text-text-secondary">Review periods, manage manual agreements, and monitor Stripe subscriptions.</p></div><button v-if="can('subscriptions.manage')" class="btn-primary" @click="begin">+ Assign subscription</button></div><p v-if="message" class="mt-5 rounded-lg bg-success-bg p-3 text-success" role="status">{{ message }}</p><p v-if="failure && !editing" class="mt-5 text-danger" role="alert">{{ failure }}</p><form class="my-6 flex flex-wrap gap-3" @submit.prevent="search=searchInput;page=1"><input v-model="searchInput" class="input max-w-sm" placeholder="Search customer email or name" aria-label="Search subscriptions"><select v-model="status" class="input w-auto" aria-label="Subscription status" @change="page=1"><option value="">All statuses</option><option v-for="value in ['active','trialing','expired','cancelled','past_due','unpaid','incomplete']" :key="value">{{ value }}</option></select><button class="btn-secondary">Search</button></form><div class="surface overflow-hidden"><LoadingState v-if="pending"/><p v-else-if="error" class="p-8" role="alert">Unable to load subscriptions. <button class="text-brand" @click="refresh()">Retry</button></p><div v-else class="overflow-x-auto"><table class="admin-table"><thead><tr><th>Customer</th><th>Plan</th><th>Status</th><th>Amount</th><th>Period ends</th><th>Source</th><th>Action</th></tr></thead><tbody><tr v-for="subscription in rows" :key="subscription.id"><td><p class="font-medium">{{ subscription.user?.name }}</p><p class="text-xs text-text-muted">{{ subscription.user?.email }}</p></td><td>{{ subscription.plan.name }}</td><td><span :class="['active','trialing'].includes(subscription.effective_status)?'badge-success':'badge-warning'">{{ subscription.effective_status }}</span><p v-if="subscription.cancel_at_period_end" class="mt-1 text-xs text-text-muted">Cancels at period end</p></td><td>{{ money(subscription.amount,subscription.currency) }} / {{ subscription.interval }}</td><td>{{ billingDate(subscription.ends_at) }}</td><td>{{ subscription.provider }}</td><td><button v-if="can('subscriptions.manage') && subscription.provider==='manual' && subscription.status!=='cancelled'" class="text-danger" @click="cancelling=subscription">Cancel</button><span v-else class="text-xs text-text-muted">{{ subscription.provider==='stripe'?'Managed in Stripe':'—' }}</span></td></tr><tr v-if="!rows.length"><td colspan="7" class="py-12 text-center">No subscriptions match your filters.</td></tr></tbody></table></div><AdminPagination v-if="pagination" :current="pagination.current_page" :last="pagination.last_page" :total="pagination.total" :pending="pending" @change="page=$event"/></div><AdminDialog v-if="editing" title="Assign a manual subscription" @close="editing=false"><form class="grid gap-4" @submit.prevent="assign"><p class="text-sm text-text-secondary">For agreements paid outside Stripe. This action does not charge the customer.</p><div class="flex gap-2"><input v-model="customerSearch" class="input" aria-label="Find customer" placeholder="Customer name or email"><button type="button" class="btn-secondary" :disabled="finding" @click="findCustomers">Find</button></div><label class="label">Customer<select v-model.number="form.user_id" class="input mt-2" required><option :value="0" disabled>Select customer</option><option v-for="customer in customers" :key="customer.id" :value="customer.id">{{ customer.name }} · {{ customer.email }}</option></select></label><label class="label">Plan<select v-model.number="form.plan_id" class="input mt-2" required><option :value="0" disabled>Select plan</option><option v-for="plan in plans?.data.filter(p=>p.is_active)" :key="plan.id" :value="plan.id">{{ plan.name }} · {{ plan.currency }}</option></select></label><div class="grid grid-cols-2 gap-4"><label class="label">Billing interval<select v-model="form.interval" class="input mt-2"><option value="month">Monthly</option><option value="year">Yearly</option></select></label><label class="label">Agreed amount<input v-model="form.amount" class="input mt-2" type="number" min="0" step="0.01" required></label></div><div class="grid grid-cols-2 gap-4"><label class="label">Start date<input v-model="form.starts_at" class="input mt-2" type="date" required></label><label class="label">End date<input v-model="form.ends_at" class="input mt-2" type="date" :min="form.starts_at" required></label></div><label class="label">Status<select v-model="form.status" class="input mt-2"><option value="active">Active</option><option value="trialing">Trial</option></select></label><label class="label">Internal notes<textarea v-model="form.notes" class="input mt-2" maxlength="2000"/></label><p v-if="failure" role="alert" class="text-danger">{{ failure }}</p><button class="btn-primary" :disabled="saving">{{ saving?'Assigning…':'Assign subscription' }}</button></form></AdminDialog><AdminDialog v-if="cancelling" title="Cancel subscription?" @close="cancelling=null"><p class="text-text-secondary">{{ cancelling.user?.email }} will lose access to this plan immediately. Existing links are retained. This does not issue a refund.</p><div class="mt-6 flex justify-end gap-3"><button class="btn-secondary" @click="cancelling=null">Keep subscription</button><button class="btn-danger" :disabled="saving" @click="async()=>{if(await mutate(`management/subscriptions/${cancelling!.id}/cancel`)) cancelling=null}">Confirm cancellation</button></div></AdminDialog></div></template>
